cat <<'EOF' > app/javascript/controllers/drag_and_drop_controller.js
import { Controller } from "@hotwired/stimulus"
import { FetchRequest } from "@rails/request.js"
import { Turbo } from "@hotwired/turbo-rails"

export default class extends Controller {
  static classes = [ "draggedItem", "hoverContainer" ]
  static targets = [ "container", "item" ]
  static values = {
    desktopBreakpoint: { type: String, default: "(min-width: 640px)" }
  }

  #pendingSave = Promise.resolve()

  connect() {
    this.mediaQuery = window.matchMedia(this.desktopBreakpointValue)
    this.handleViewportChange = this.#updateDraggableItems.bind(this)
    this.mediaQuery.addEventListener("change", this.handleViewportChange)
    this.#updateDraggableItems()
  }

  disconnect() {
    this.mediaQuery?.removeEventListener("change", this.handleViewportChange)
    this.#cleanup()
  }

  itemTargetConnected(element) {
    if (this.mediaQuery) {
      element.draggable = this.#isDesktop
    }
  }

  dragStart(event) {
    if (!this.#isDesktop) return
    if (event.target.closest("dialog[open], input, textarea, [contenteditable]")) return

    const item = event.target.closest('[data-drag-and-drop-target~="item"]')
    const container = item?.closest('[data-drag-and-drop-target~="container"]')
    if (!item || !container || !this.element.contains(container)) return

    this.#cleanup()
    this.draggedItem = item
    this.sourceContainer = container

    this.#clearNavigableSelection(container, item)
    item.classList.add(this.#draggedClass)

    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = "move"
      event.dataTransfer.setData("text/plain", item.id)
    }
  }

  dragEnter(event) {
    this.#updateHoveredContainer(event)
  }

  dragOver(event) {
    this.#updateHoveredContainer(event)
  }

  dragLeave(event) {
    if (!this.draggedItem || !this.hoveredContainer) return

    const relatedTarget = event.relatedTarget
    if (relatedTarget) {
      if (!this.hoveredContainer.contains(relatedTarget)) {
        this.#clearHoverContainer()
      }
    } else if (!this.#isPointInside(event.clientX, event.clientY, this.hoveredContainer)) {
      this.#clearHoverContainer()
    }
  }

  drop(event) {
    if (!this.draggedItem) return

    const targetContainer = event.target.closest('[data-drag-and-drop-target~="container"]')
    const item = this.draggedItem
    const sourceContainer = this.sourceContainer

    this.#cleanup()

    if (!targetContainer || !sourceContainer || targetContainer === sourceContainer || !this.element.contains(targetContainer)) {
      return
    }

    event.preventDefault()

    this.#moveItem(item, sourceContainer, targetContainer)
    this.#enqueueSave(item, targetContainer)
  }

  dragEnd() {
    this.#cleanup()
  }

  get #isDesktop() {
    return this.mediaQuery?.matches ?? true
  }

  get #draggedClass() {
    return this.hasDraggedItemClass ? this.draggedItemClass : "drag-and-drop__dragged-item"
  }

  get #hoverClass() {
    return this.hasHoverContainerClass ? this.hoverContainerClass : "drag-and-drop__hover-container"
  }

  #updateDraggableItems() {
    const draggable = this.#isDesktop
    this.itemTargets.forEach(item => {
      item.draggable = draggable
    })
  }

  #updateHoveredContainer(event) {
    if (!this.draggedItem) return

    const container = event.target.closest('[data-drag-and-drop-target~="container"]')
    if (!container || container === this.sourceContainer || !this.element.contains(container)) {
      this.#clearHoverContainer()
      return
    }

    event.preventDefault()
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = "move"
    }

    if (this.hoveredContainer !== container) {
      this.#clearHoverContainer()
      this.hoveredContainer = container
      container.classList.add(this.#hoverClass)
    }
  }

  #clearHoverContainer() {
    if (this.hoveredContainer) {
      this.hoveredContainer.classList.remove(this.#hoverClass)
      this.hoveredContainer = null
    }
  }

  #cleanup() {
    if (this.draggedItem) {
      this.draggedItem.classList.remove(this.#draggedClass)
      this.draggedItem = null
    }
    this.#clearHoverContainer()
    this.sourceContainer = null
  }

  #isPointInside(clientX, clientY, element) {
    if (clientX === 0 && clientY === 0) return false

    const rect = element.getBoundingClientRect()
    return clientX >= rect.left && clientX <= rect.right && clientY >= rect.top && clientY <= rect.bottom
  }

  #clearNavigableSelection(container, item) {
    item.removeAttribute("aria-selected")

    const listElement = container.querySelector('[data-controller~="navigable-list"]')
    if (listElement) {
      const listController = this.application.getControllerForElementAndIdentifier(listElement, "navigable-list")
      if (listController?.isSelected(item)) {
        listController.clearSelection()
      }
    }
  }

  #moveItem(item, sourceContainer, targetContainer) {
    const frame = targetContainer.querySelector("turbo-frame[src]")
    const frameIsLoading = frame && (frame.hasAttribute("busy") || !targetContainer.querySelector(".cards__list"))

    this.#updateCardAppearance(item, targetContainer)

    if (frameIsLoading) {
      item.remove()
      frame.loaded.then(() => {
        if (!document.getElementById(item.id)) {
          this.#insertItemIntoContainer(item, targetContainer)
          this.#updateColumnProgress(targetContainer)
        }
      })
    } else {
      this.#insertItemIntoContainer(item, targetContainer)
    }

    this.#adjustColumnCount(sourceContainer, -1)
    this.#adjustColumnCount(targetContainer, 1)
  }

  #insertItemIntoContainer(item, container) {
    const list = container.querySelector(".cards__list")
    if (!list) return

    const insertionParent = list.querySelector("turbo-frame") || list
    const cards = Array.from(list.querySelectorAll('[data-drag-and-drop-target~="item"]')).filter(card => card !== item)
    const goldenFirst = container.dataset.goldenFirst !== "false"
    const isGolden = item.classList.contains("golden-effect")

    if (!goldenFirst || isGolden) {
      if (cards.length > 0) {
        cards[0].before(item)
      } else {
        insertionParent.prepend(item)
      }
    } else {
      const firstNonGoldenCard = cards.find(card => !card.classList.contains("golden-effect"))
      if (firstNonGoldenCard) {
        firstNonGoldenCard.before(item)
      } else if (cards.length > 0) {
        cards[cards.length - 1].after(item)
      } else {
        insertionParent.prepend(item)
      }
    }
  }

  #updateCardAppearance(item, container) {
    const cardColor = container.dataset.cardColor || "var(--color-card-default)"
    const status = container.dataset.cardStatus || "active"

    item.style.setProperty("--card-color", cardColor)
    item.classList.toggle("card--active", status === "active")
    item.classList.toggle("card--postponed", status === "postponed")

    item.querySelector(".card__closed")?.remove()
    item.querySelector('[id^="assignees_card_"]')?.toggleAttribute("hidden", status === "closed")
    item.querySelector(".bubble")?.setAttribute("hidden", "")

    const updatedTime = item.querySelector(".card__meta-text--updated time")
    if (updatedTime) {
      updatedTime.setAttribute("datetime", Math.floor(Date.now() / 1000))
      updatedTime.dispatchEvent(new CustomEvent("turbo:morph-element", { bubbles: true }))
    }
  }

  #adjustColumnCount(container, delta) {
    const countElement = container.querySelector(".cards__expander-count")
    if (countElement) {
      const currentCount = parseInt(countElement.dataset.count ?? countElement.textContent, 10) || 0
      const nextCount = Math.max(0, currentCount + delta)
      countElement.dataset.count = nextCount
      countElement.textContent = nextCount > 99 ? "99+" : nextCount
    }

    this.#updateColumnProgress(container)
  }

  #updateColumnProgress(container) {
    const expanderButton = container.querySelector(".cards__expander")
    const list = container.querySelector(".cards__list")
    if (expanderButton && list) {
      const loadedCardsCount = list.querySelectorAll('[data-drag-and-drop-target~="item"]').length
      expanderButton.style.setProperty("--card-count", Math.min(loadedCardsCount, 15))
    }
  }

  #enqueueSave(item, targetContainer) {
    const urlTemplate = targetContainer.dataset.dropUrl
    const method = targetContainer.dataset.dropMethod || "post"
    const cardId = item.dataset.id
    if (!urlTemplate || !cardId) return

    const url = urlTemplate.replace("__id__", encodeURIComponent(cardId))

    this.#pendingSave = this.#pendingSave
      .then(() => this.#performSave(method, url))
      .catch(() => this.#recoverFromFailedSave())
  }

  async #performSave(method, url) {
    const request = new FetchRequest(method, url, { responseKind: "json", keepalive: true })
    const response = await request.perform()
    if (!response.ok) {
      throw new Error(`Failed to save card move (${response.statusCode})`)
    }
  }

  #recoverFromFailedSave() {
    Turbo.visit(window.location.href, { action: "replace" })
  }
}
EOF

cat <<'EOF' > test/models/card/postponable_test.rb
require "test_helper"

class Card::PostponableTest < ActiveSupport::TestCase
  setup do
    Current.session = sessions(:david)
  end

  test "check the postponed status of a card" do
    card = cards(:logo)

    assert_not card.postponed?
    assert card.active?

    card.postpone
    assert card.postponed?
    assert_not card.active?
  end

  test "postpone and resume a card" do
    card = cards(:text)

    assert_changes -> { card.reload.postponed? }, to: true do
      assert_difference -> { card.events.count }, +1 do
        card.postpone
      end
    end

    assert_equal users(:david), card.not_now.user
    assert card.events.last.action.card_postponed?

    assert_changes -> { card.reload.postponed? }, to: false do
      card.resume
    end
  end

  test "postpone a closed card reopens once and marks postponed" do
    card = cards(:shipping)
    assert card.closed?

    assert_difference -> { card.events.count }, +2 do
      card.postpone
    end

    assert_not card.closed?
    assert card.postponed?
    assert_nil card.reload.column
    assert_equal %w[ card_reopened card_postponed ], card.events.order(:created_at).last(2).pluck(:action)
  end

  test "auto_postpone a card" do
    card = cards(:text)

    assert_changes -> { card.reload.postponed? }, to: true do
      assert_difference -> { card.events.count }, +1 do
        card.auto_postpone
      end
    end

    assert card.events.last.action.card_auto_postponed?
  end

  test "scopes" do
    logo = cards(:logo)
    text = cards(:text)

    logo.postpone

    assert_includes Card.postponed, logo
    assert_not_includes Card.postponed, text

    assert_includes Card.active, text
    assert_not_includes Card.active, logo
  end
end
EOF

cat <<'EOF' > test/system/drag_and_drop_test.rb
require "application_system_test_case"

class DragAndDropTest < ApplicationSystemTestCase
  include ActionView::RecordIdentifier

  setup do
    sign_in_as(users(:kevin))
    @board = boards(:writebook)
  end

  test "dragging a card across columns and statuses persists each change" do
    card = cards(:buy_domain)
    in_progress = columns(:writebook_in_progress)
    on_hold = columns(:writebook_on_hold)

    visit board_url(@board)

    # Maybe? -> In progress (collapsed column)
    drag_card(card, to: column_selector(in_progress))
    assert_column_count(in_progress, 2)
    assert_column_count("#maybe", 0)
    wait_until { card.reload.column == in_progress }

    # Expand In progress and verify card is already inside it
    expand_column(in_progress)
    within(column_selector(in_progress)) do
      assert_selector card_selector(card)
    end

    # In progress -> On Hold (empty column)
    drag_card(card, to: column_selector(on_hold))
    assert_column_count(in_progress, 1)
    assert_column_count(on_hold, 1)
    wait_until { card.reload.column == on_hold }

    # On Hold -> Not Now
    expand_column(on_hold)
    drag_card(card, to: "#not-now")
    assert_column_count(on_hold, 0)
    assert_column_count("#not-now", 1)
    within(column_selector(on_hold)) do
      assert_selector ".blank-slate--drag", text: "Drag cards here"
    end
    wait_until { card.reload.postponed? }

    # Not Now -> Done
    expand_column("#not-now")
    drag_card(card, to: "#closed-cards")
    assert_column_count("#not-now", 0)
    assert_column_count("#closed-cards", 2)
    wait_until { card.reload.closed? }

    # Done -> Maybe?
    expand_column("#closed-cards")
    drag_card(card, to: "#maybe")
    assert_column_count("#closed-cards", 1)
    assert_column_count("#maybe", 1)
    within("#maybe") do
      assert_selector card_selector(card)
    end
    wait_until { card.reload.awaiting_triage? }
  end

  test "dragging from Done to Not Now and into a column" do
    card = cards(:shipping)
    review = columns(:writebook_review)

    visit board_url(@board)
    expand_column("#closed-cards")

    drag_card(card, to: "#not-now")
    wait_until { card.reload.postponed? && !card.closed? }

    expand_column("#not-now")
    drag_card(card, to: column_selector(review))
    wait_until { card.reload.triaged? && card.column == review }
  end

  test "columns keep their own order and dragging within the same column is a no-op" do
    triage = columns(:writebook_triage)
    golden_card = cards(:logo)
    regular_card = cards(:layout)
    moved_card = cards(:buy_domain)

    visit board_url(@board)
    expand_column(triage)

    assert_equal [ dom_id(golden_card, :article), dom_id(regular_card, :article) ], card_ids_in(column_selector(triage))

    # Dragging within Triage does not reorder cards
    drag_card(regular_card, to: card_selector(golden_card))
    assert_equal [ dom_id(golden_card, :article), dom_id(regular_card, :article) ], card_ids_in(column_selector(triage))

    # Dropping a non-golden card into Triage places it after golden cards and before other non-golden cards
    drag_card(moved_card, to: column_selector(triage))
    expected_order = [
      dom_id(golden_card, :article),
      dom_id(moved_card, :article),
      dom_id(regular_card, :article)
    ]
    assert_equal expected_order, card_ids_in(column_selector(triage))
    wait_until { moved_card.reload.column == triage }

    # Dropping a golden card into In progress places it at the very top
    in_progress = columns(:writebook_in_progress)
    existing_in_progress = cards(:text)
    drag_card(golden_card, to: column_selector(in_progress))
    expand_column(in_progress)
    assert_equal [ dom_id(golden_card, :article), dom_id(existing_in_progress, :article) ], card_ids_in(column_selector(in_progress))
    wait_until { golden_card.reload.column == in_progress }
  end

  test "drop updates the board instantly before save completes and nothing shifts afterwards" do
    card = cards(:buy_domain)
    triage = columns(:writebook_triage)

    visit board_url(@board)
    expand_column(triage)

    # Hold the network save in flight so we can inspect the board while saving
    page.execute_script(<<~JS)
      window.__originalFetch = window.fetch
      window.__pendingSaveResolve = null
      window.fetch = function(url, options) {
        if (options && options.method && options.method !== "GET") {
          return new Promise(resolve => {
            window.__pendingSaveResolve = () => resolve(window.__originalFetch(url, options))
          })
        }
        return window.__originalFetch(url, options)
      }
    JS

    drag_card(card, to: column_selector(triage))

    # While save is still paused, the card is already in Triage in its final position
    assert_nil card.reload.column
    expected_order = [
      dom_id(cards(:logo), :article),
      dom_id(card, :article),
      dom_id(cards(:layout), :article)
    ]
    assert_equal expected_order, card_ids_in(column_selector(triage))
    assert_no_selector ".drag-and-drop__dragged-item"
    assert_no_selector ".drag-and-drop__hover-container"

    rect_before_save = card_rect(card)

    # Complete the save and also broadcast a board refresh
    page.execute_script("window.__pendingSaveResolve(); window.fetch = window.__originalFetch;")
    wait_until { card.reload.column == triage }
    perform_enqueued_jobs only: Turbo::Streams::BroadcastStreamJob

    assert_equal expected_order, card_ids_in(column_selector(triage))
    assert_equal rect_before_save, card_rect(card)
  end

  test "dragged card dims and hovered target column lights up" do
    card = cards(:buy_domain)
    triage = columns(:writebook_triage)
    in_progress = columns(:writebook_in_progress)

    visit board_url(@board)

    # Start drag: card gets dimmed class, source column does not light up
    page.execute_script(<<~JS, find(card_selector(card)))
      const card = arguments[0]
      window.__dt = new DataTransfer()
      card.dispatchEvent(new DragEvent("dragstart", { bubbles: true, cancelable: true, dataTransfer: window.__dt }))
      card.dispatchEvent(new DragEvent("dragover", { bubbles: true, cancelable: true, dataTransfer: window.__dt }))
    JS

    assert_selector "#{card_selector(card)}.drag-and-drop__dragged-item"
    assert_no_selector "#maybe.drag-and-drop__hover-container"

    # Drag over Triage: Triage lights up
    page.execute_script(<<~JS, find(column_selector(triage)))
      arguments[0].dispatchEvent(new DragEvent("dragover", { bubbles: true, cancelable: true, dataTransfer: window.__dt }))
    JS
    assert_selector "#{column_selector(triage)}.drag-and-drop__hover-container"

    # Move pointer to In progress: Triage un-highlights and In progress lights up
    page.execute_script(<<~JS, find(column_selector(in_progress)))
      arguments[0].dispatchEvent(new DragEvent("dragover", { bubbles: true, cancelable: true, dataTransfer: window.__dt }))
    JS
    assert_no_selector "#{column_selector(triage)}.drag-and-drop__hover-container"
    assert_selector "#{column_selector(in_progress)}.drag-and-drop__hover-container"

    # Cancel drag: both classes are cleaned up
    page.execute_script(<<~JS, find(card_selector(card)))
      arguments[0].dispatchEvent(new DragEvent("dragend", { bubbles: true, cancelable: true, dataTransfer: window.__dt }))
    JS
    assert_no_selector ".drag-and-drop__dragged-item"
    assert_no_selector ".drag-and-drop__hover-container"
  end

  test "clicking a card still navigates to it" do
